func (u *UsuarioUpsertBulk) Update(set func(*UsuarioUpsert)) *UsuarioUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&UsuarioUpsert{UpdateSet: update})
	}))
	return u
}

